package cn.nulladev.modularmagic;

import cn.nulladev.modularmagic.research.*;
import cn.nulladev.modularmagic.network.EditorNetworking;
import cn.nulladev.modularmagic.client.ResearchScreen;
import net.minecraft.client.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.GameType;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.network.PacketDistributor;

@EventBusSubscriber(modid=ModularMagic.MOD_ID,value=Dist.CLIENT)
public final class ResearchClientSmoke{
    private static int ticks,stage,changed,assemblyStep;
    private static boolean carvingSuppliesMoved,outputTaken,carvingSelected;
    private static final BlockPos POS=new BlockPos(16,100,16);
    @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!Boolean.getBoolean("modularmagic.researchSmoke"))return;var mc=Minecraft.getInstance();if(++ticks>3000){ModularMagic.LOGGER.error("RESEARCH_SMOKE_TIMEOUT stage={}",stage);mc.stop();return;}if(mc.player==null||mc.getSingleplayerServer()==null||ticks-changed<20)return;
        try{
            if(stage==0){mc.options.pauseOnLostFocus=false;mc.player.getInventory().selected=0;mc.options.guiScale().set(2);mc.resizeDisplay();server(mc,()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.setGameMode(GameType.SURVIVAL);p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.fallDistance=0;for(int x=12;x<=20;x++)for(int z=12;z<=20;z++)p.serverLevel().setBlockAndUpdate(new BlockPos(x,99,z),net.minecraft.world.level.block.Blocks.SMOOTH_STONE.defaultBlockState());p.setData(ResearchKnowledge.DATA,new CompoundTag());ResearchCatalog.get("K00").nodes().forEach(n->ResearchKnowledge.learn(p,n));ResearchKnowledge.save(p,"observed:K01","yes");ResearchKnowledge.save(p,"active","K01");p.getInventory().clearContent();p.getInventory().selected=0;p.getInventory().setItem(0,ResearchNoteItem.create("K01",false));p.getInventory().setItem(1,ResearchContent.INK.toStack());p.serverLevel().setBlockAndUpdate(POS,ResearchContent.TABLE.get().defaultBlockState());p.teleportTo(POS.getX()+.5,POS.getY()+1,POS.getZ()+2);ResearchContent.open(p,POS,false);});next();}
            else if(stage==1){if(!(mc.screen instanceof ResearchScreen)||!(mc.player.containerMenu instanceof ResearchMenu m)||m.document==null)return;if(m.slots.subList(10,m.slots.size()).stream().anyMatch(slot->!slot.isActive()))throw new IllegalStateException("Research must show the entire backpack");if(m.inkCost<=0||m.inkAvailable<m.inkCost)throw new IllegalStateException("Notes and pack ink must be ready without moving physical slots");click(mc,80,84,0);click(mc,80,84,1);click(mc,80,height(mc)-16,0);next();}
            else if(stage==2){if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.paid)return;
                if(assemblyStep<4){if(m.document.nodes().size()!=assemblyStep+1)return;String[] pieces={"trigger/self_pos","action/processor","selector/self","effect/push"};String[] parents={"root/instant","root/instant","action/processor","action/processor"};String[] slots={"trigger_type","action","selector","processors"};insert(mc,m,pieces[assemblyStep],parents[assemblyStep],slots[assemblyStep]);assemblyStep++;changed=ticks;return;}
                if(assemblyStep==4){if(m.document.nodes().size()!=5)return;click(mc,width(mc)-15,14,0);nodeClick(mc,m,"effect/push",1);assemblyStep++;changed=ticks;return;}
                if(assemblyStep==5){if(m.document.nodes().size()!=4)return;insert(mc,m,"effect/push","action/processor","processors");assemblyStep++;changed=ticks;return;}
                if(assemblyStep==6){if(m.document.nodes().size()!=5)return;editSpeed(mc,m,"0.375");assemblyStep++;changed=ticks;return;}
                if(assemblyStep==7){if(!m.document.nodes().stream().filter(n->n.template.equals("effect/push")).findFirst().orElseThrow().parameters.get("speed").equals("0.375"))return;editSpeed(mc,m,m.reference.nodes().stream().filter(n->n.template.equals("effect/push")).findFirst().orElseThrow().parameters.get("speed"));assemblyStep++;changed=ticks;return;}
                if(assemblyStep==8){if(!ResearchCatalog.equivalent(m.document.root,m.reference.root))return;screenshot(mc,"modularmagic-research.png");click(mc,width(mc)-194-133,39,0);assemblyStep++;changed=ticks;return;}
                screenshot(mc,"modularmagic-research-reference.png");click(mc,width(mc)-194-48,39,0);next();}
            else if(stage==3){if(!(mc.player.containerMenu instanceof ResearchMenu m)||m.document==null||m.document.nodes().size()<4)return;click(mc,80,height(mc)-16,0);next();}
            else if(stage==4){if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.notice.equals("success"))return;server(mc,()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());if(!ResearchKnowledge.knows(p,"effect/push"))throw new IllegalStateException("Research did not teach its node");p.closeContainer();p.getInventory().setItem(0,ResearchContent.INK.toStack());p.getInventory().setItem(1,ResearchContent.BLANK.toStack());p.serverLevel().setBlockAndUpdate(POS,ResearchContent.CARVER.get().defaultBlockState());ResearchContent.open(p,POS,true);});next();}
            else if(stage==5){if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.carving)return;if(!carvingSuppliesMoved){for(int slot:new int[]{37,38})mc.gameMode.handleInventoryMouseClick(m.containerId,slot,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);carvingSuppliesMoved=true;changed=ticks;return;}if(m.supplies.getItem(0).isEmpty())return;if(!carvingSelected){choose(mc,m,"effect/push");carvingSelected=true;changed=ticks;return;}screenshot(mc,"modularmagic-carving.png");mc.screen.mouseClicked((mc.getWindow().getGuiScaledWidth()-244)/2+211,(mc.getWindow().getGuiScaledHeight()-232)/2+135,0);next();}
            else if(stage==6){if(!(mc.player.containerMenu instanceof ResearchMenu m)||!m.notice.equals("carved"))return;if(!outputTaken){if(m.supplies.getItem(9).isEmpty())return;mc.gameMode.handleInventoryMouseClick(m.containerId,9,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);outputTaken=true;changed=ticks;return;}if(!m.supplies.getItem(9).isEmpty())return;server(mc,()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.closeContainer();ResearchKnowledge.learn(p,"K31");p.getInventory().setItem(2,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.WATER_BUCKET));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,PlaceholderContent.ITEM.toStack());PlaceholderContent.ITEM.get().use(p.level(),p,net.minecraft.world.InteractionHand.MAIN_HAND);var menu=(PlaceholderMenu)p.containerMenu;menu.inputs.setItem(1,cn.nulladev.modularmagic.crafting.ArtificeContent.PLATES.get("K03").toStack());menu.inputs.setItem(2,cn.nulladev.modularmagic.crafting.ArtificeContent.PLATES.get("K07").toStack());menu.inputs.setItem(3,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.WATER_BUCKET));menu.inputs.setItem(4,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.WATER_BUCKET));});next();}
            else if(stage==7){if(!(mc.player.containerMenu instanceof PlaceholderMenu m))return;for(int slot:new int[]{40,9,40})mc.gameMode.handleInventoryMouseClick(m.containerId,slot,0,net.minecraft.world.inventory.ClickType.PICKUP,mc.player);next();}
            else if(stage==8){if(!(mc.player.containerMenu instanceof PlaceholderMenu m)||m.result.isEmpty())return;screenshot(mc,"modularmagic-placeholder.png");mc.gameMode.handleInventoryMouseClick(m.containerId,10,0,net.minecraft.world.inventory.ClickType.PICKUP,mc.player);next();}
            else if(stage==9){if(!(mc.player.containerMenu instanceof PlaceholderMenu m)||PlaceholderItem.target(m.getCarried())==null)return;mc.player.closeContainer();var registry=Class.forName("vazkii.patchouli.common.book.BookRegistry");var books=(java.util.Map<?,?>)registry.getField("books").get(registry.getField("INSTANCE").get(null));var book=books.get(ModularMagic.id("assembly_guide"));var contents=book.getClass().getMethod("getContents").invoke(book);if((boolean)contents.getClass().getMethod("isErrored").invoke(contents))throw new IllegalStateException("Guide failed to load");var entries=(java.util.Map<?,?>)contents.getClass().getField("entries").get(contents);if(!entries.containsKey(ModularMagic.id("energy/generator_curing"))||!entries.containsKey(ModularMagic.id("research/placeholders")))throw new IllegalStateException("Missing guide chapters");var client=Class.forName("vazkii.patchouli.client.book.ClientBookRegistry");client.getMethod("displayBookGui",net.minecraft.resources.ResourceLocation.class,net.minecraft.resources.ResourceLocation.class,int.class).invoke(client.getField("INSTANCE").get(null),ModularMagic.id("assembly_guide"),ModularMagic.id("energy/generator_tnt"),0);next();}
            else if(stage==10){screenshot(mc,"modularmagic-generator-guide.png");var surfaces=new java.util.HashSet<String>();for(var block:java.util.List.of(cn.nulladev.modularmagic.registry.ModContent.WRITING_TABLE.get(),ResearchContent.TABLE.get(),ResearchContent.CARVER.get())){var model=mc.getBlockRenderer().getBlockModel(block.defaultBlockState());for(var q:model.getQuads(null,null,net.minecraft.util.RandomSource.create(0))){var id=q.getSprite().contents().name().toString();if(id.endsWith("surface"))surfaces.add(id);}}if(surfaces.size()!=3)throw new IllegalStateException("All three tables must use distinct top artwork: "+surfaces);for(String id:cn.nulladev.modularmagic.generator.GeneratorCatalog.RULES.keySet()){var s=cn.nulladev.modularmagic.generator.GeneratorItem.create(id);var lines=new java.util.ArrayList<net.minecraft.network.chat.Component>();s.getItem().appendHoverText(s,net.minecraft.world.item.Item.TooltipContext.of(mc.level),lines,net.minecraft.world.item.TooltipFlag.NORMAL);if(!lines.isEmpty())throw new IllegalStateException("Generator descriptions belong in the guide");}var client=Class.forName("vazkii.patchouli.client.book.ClientBookRegistry");client.getMethod("displayBookGui",net.minecraft.resources.ResourceLocation.class,net.minecraft.resources.ResourceLocation.class,int.class).invoke(client.getField("INSTANCE").get(null),ModularMagic.id("assembly_guide"),ModularMagic.id("opening"),0);next();}
            else if(stage==11){screenshot(mc,"modularmagic-opening-story.png");ModularMagic.LOGGER.info("MODULARMAGIC_RESEARCH_SMOKE_PASSED");stage=99;mc.stop();}
        }catch(Throwable ex){ModularMagic.LOGGER.error("RESEARCH_SMOKE_FAILED stage="+stage,ex);stage=99;mc.stop();}
    }
    private static void server(Minecraft mc,Runnable r){mc.getSingleplayerServer().execute(r);}
    private static void choose(Minecraft mc,ResearchMenu m,String piece){if(m.carving){int i=new java.util.ArrayList<>(m.palette.keySet()).indexOf(piece);mc.screen.mouseClicked((mc.getWindow().getGuiScaledWidth()-244)/2+9+i%7*24+10,(mc.getWindow().getGuiScaledHeight()-232)/2+27+i/7*24+10,0);return;}int w=Math.min(mc.getWindow().getGuiScaledWidth()-16,620),h=Math.min(mc.getWindow().getGuiScaledHeight()-16,400),left=(mc.getWindow().getGuiScaledWidth()-w)/2,top=(mc.getWindow().getGuiScaledHeight()-h)/2,cols=7,index=new java.util.ArrayList<>(m.palette.keySet()).indexOf(piece);mc.screen.mouseClicked(left+w-178+(index%cols)*24+10,top+57+(index/cols)*24+10,0);}
    private static void insert(Minecraft mc,ResearchMenu m,String piece,String parent,String slot){choose(mc,m,piece);var rows=new java.util.ArrayList<String>();flatten(m.document.root,rows);int row=rows.indexOf(parent+":"+slot);if(row<0)throw new IllegalStateException("Missing slot "+slot);int w=Math.min(mc.getWindow().getGuiScaledWidth()-16,620),h=Math.min(mc.getWindow().getGuiScaledHeight()-16,400);mc.screen.mouseClicked((mc.getWindow().getGuiScaledWidth()-w)/2+80,(mc.getWindow().getGuiScaledHeight()-h)/2+53+row*21+10,0);}
    private static void flatten(cn.nulladev.modularmagic.spell.SpellDocument.Node n,java.util.List<String> out){out.add(n.template);for(var s:n.schema().slots()){for(var c:n.children.get(s.key()))flatten(c,out);if(n.children.get(s.key()).isEmpty()||s.list())out.add(n.template+":"+s.key());}}
    private static int width(Minecraft mc){return Math.min(mc.getWindow().getGuiScaledWidth()-16,620);}
    private static int height(Minecraft mc){return Math.min(mc.getWindow().getGuiScaledHeight()-16,400);}
    private static void click(Minecraft mc,int x,int y,int button){mc.screen.mouseClicked((mc.getWindow().getGuiScaledWidth()-width(mc))/2+x,(mc.getWindow().getGuiScaledHeight()-height(mc))/2+y,button);}
    private static void nodeClick(Minecraft mc,ResearchMenu m,String id,int button){var rows=new java.util.ArrayList<String>();flatten(m.document.root,rows);int row=rows.indexOf(id);if(row<0)throw new IllegalStateException("Missing node "+id);click(mc,80,53+row*21+10,button);}
    private static void editSpeed(Minecraft mc,ResearchMenu m,String speed){nodeClick(mc,m,"effect/push",0);var edit=mc.screen.children().stream().filter(e->e instanceof net.minecraft.client.gui.components.EditBox).map(e->(net.minecraft.client.gui.components.EditBox)e).findFirst().orElseThrow();edit.setValue(speed);click(mc,width(mc)-194-52,39,0);}
    private static void send(ResearchMenu m,String op){PacketDistributor.sendToServer(new EditorNetworking.Edit(m.containerId,m.revision,"{\"op\":\""+op+"\"}"));}
    private static void next(){stage++;changed=ticks;}
    private static void screenshot(Minecraft mc,String name){Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),c->ModularMagic.LOGGER.info("RESEARCH_SCREENSHOT: {}",c.getString()));}
}
